7	import type { Config } from '../../config/config.js';
8	import { isAutoModel, resolveModel } from '../../config/models.js';
9	import type { BaseLlmClient } from '../../core/baseLlmClient.js';
10	import type {
11	  RoutingContext,
12	  RoutingDecision,
13	  RoutingStrategy,
14	} from '../routingStrategy.js';
15	
16	/**
17	 * Handles cases where the user explicitly specifies a model (override).
18	 */
19	export class OverrideStrategy implements RoutingStrategy {
20	  readonly name = 'override';
21	
22	  async route(
23	    context: RoutingContext,
24	    config: Config,
25	    _baseLlmClient: BaseLlmClient,
26	  ): Promise<RoutingDecision | null> {
27	    const overrideModel = context.requestedModel ?? config.getModel();
28	
29	    // If the model is 'auto' we should pass to the next strategy.
30	    if (isAutoModel(overrideModel)) {
31	      return null;
32	    }
33	
34	    // Return the overridden model name.
35	    return {
36	      model: resolveModel(
37	        overrideModel,
38	        config.getGemini31LaunchedSync?.() ?? false,
39	      ),
40	      metadata: {
41	        source: this.name,
42	        latencyMs: 0,
43	        reasoning: `Routing bypassed by forced model directive. Using: ${overrideModel}`,
44	      },
45	    };
46	  }
47	}
