import type { Config } from '../../config/config.js';
import {
  DEFAULT_GEMINI_MODEL,
  DEFAULT_GEMINI_MODEL_AUTO,
  DEFAULT_GEMINI_FLASH_MODEL,
  PREVIEW_GEMINI_MODEL,
  PREVIEW_GEMINI_MODEL_AUTO,
  PREVIEW_GEMINI_FLASH_MODEL,
  isAutoModel,
} from '../../config/models.js';
import { ApprovalMode } from '../../policy/types.js';
import type { BaseLlmClient } from '../../core/baseLlmClient.js';
import type {
  RoutingContext,
  RoutingDecision,
  RoutingStrategy,
} from '../routingStrategy.js';

/**
 * Selects the best model variant based on the current phase of a planning
 * workflow. While planning (ApprovalMode is PLAN) it routes to the high
 * reasoning Pro model; once a plan has been approved it routes to the faster
 * Flash model for execution. Only applies when an auto model is active.
 */
export class ApprovalModeStrategy implements RoutingStrategy {
  readonly name = 'approval-mode';

  async route(
    context: RoutingContext,
    config: Config,
    _baseLlmClient: BaseLlmClient,
  ): Promise<RoutingDecision | null> {
    const activeModel = context.requestedModel ?? config.getModel();

    // Only participate when using automatic model selection.
    if (!isAutoModel(activeModel)) {
      return null;
    }

    // Respect the opt-out for plan mode routing.
    if (!config.getPlanModeRoutingEnabled()) {
      return null;
    }

    const approvalMode = config.getApprovalMode();
    const approvedPlanPath = config.getApprovedPlanPath();

    // Nothing to route unless we are planning or have an approved plan.
    if (approvalMode !== ApprovalMode.PLAN && !approvedPlanPath) {
      return null;
    }

    const startTime = Date.now();

    if (approvalMode === ApprovalMode.PLAN) {
      const reasoning = 'Routing to Pro model because ApprovalMode is PLAN.';
      if (activeModel === DEFAULT_GEMINI_MODEL_AUTO) {
        return {
          model: DEFAULT_GEMINI_MODEL,
          metadata: {
            source: this.name,
            latencyMs: Date.now() - startTime,
            reasoning,
          },
        };
      }
      if (activeModel === PREVIEW_GEMINI_MODEL_AUTO) {
        return {
          model: PREVIEW_GEMINI_MODEL,
          metadata: {
            source: this.name,
            latencyMs: Date.now() - startTime,
            reasoning,
          },
        };
      }
      return null;
    }

    // An approved plan exists; route to the faster Flash model for execution.
    const reasoning = `Routing to Flash model because an approved plan exists at ${approvedPlanPath}.`;
    if (activeModel === DEFAULT_GEMINI_MODEL_AUTO) {
      return {
        model: DEFAULT_GEMINI_FLASH_MODEL,
        metadata: {
          source: this.name,
          latencyMs: Date.now() - startTime,
          reasoning,
        },
      };
    }
    if (activeModel === PREVIEW_GEMINI_MODEL_AUTO) {
      return {
        model: PREVIEW_GEMINI_FLASH_MODEL,
        metadata: {
          source: this.name,
          latencyMs: Date.now() - startTime,
          reasoning,
        },
      };
    }
    return null;
  }
}
